class Solution { public int totalStrength(int[] strength){long mod=1_000_000_007L;int n=strength.length;int[] left=new int[n],right=new int[n];Deque<Integer> stack=new ArrayDeque<>();for(int i=0;i<n;i++){while(!stack.isEmpty()&&strength[stack.peek()]>=strength[i])stack.pop();left[i]=stack.isEmpty()?-1:stack.peek();stack.push(i);}stack.clear();for(int i=n-1;i>=0;i--){while(!stack.isEmpty()&&strength[stack.peek()]>strength[i])stack.pop();right[i]=stack.isEmpty()?n:stack.peek();stack.push(i);}long[] pre=new long[n+1],pp=new long[n+2];for(int i=0;i<n;i++)pre[i+1]=(pre[i]+strength[i])%mod;for(int i=0;i<=n;i++)pp[i+1]=(pp[i]+pre[i])%mod;long answer=0;for(int i=0;i<n;i++){long positive=(i-left[i])*((pp[right[i]+1]-pp[i+1]+mod)%mod)%mod;long negative=(right[i]-i)*((pp[i+1]-pp[left[i]+1]+mod)%mod)%mod;long ranges=(positive-negative+mod)%mod;answer=(answer+strength[i]*ranges)%mod;}return (int)answer;} }
